/**
 * Writing generated files: cleaning the output directory and writing new files.
 */
import fs from 'node:fs/promises';
import path from 'node:path';
import { GENERATED_HEADER_PREFIX } from './generate';

async function isGeneratedFile(file: string): Promise<boolean> {
  let handle: fs.FileHandle | undefined;
  try {
    handle = await fs.open(file, 'r');
    const buffer = Buffer.alloc(GENERATED_HEADER_PREFIX.length);
    const { bytesRead } = await handle.read(buffer, 0, buffer.length, 0);
    return buffer.toString('utf8', 0, bytesRead) === GENERATED_HEADER_PREFIX;
  } catch {
    return false;
  } finally {
    await handle?.close();
  }
}

/** Result of `cleanOutputDir`. */
export interface CleanResult {
  /** Deleted files (absolute paths). */
  removed: string[];
  /** Files left in place because nimaime-gen did not generate them (absolute paths). */
  kept: string[];
}

/**
 * Removes the files a previous `nimaime-gen` run generated in `outputDir` (files starting with
 * `// Generated by nimaime-gen`) and the directories left empty, including `outputDir` itself.
 * Other files are left untouched, so a misconfigured `outputDir` never loses user files.
 */
export async function cleanOutputDir(outputDir: string): Promise<CleanResult> {
  const result: CleanResult = { removed: [], kept: [] };

  /** Returns whether `dir` is empty afterwards. */
  const visit = async (dir: string): Promise<boolean> => {
    let entries;
    try {
      entries = await fs.readdir(dir, { withFileTypes: true });
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return true;
      throw error;
    }
    let empty = true;
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        if (await visit(full)) await fs.rmdir(full);
        else empty = false;
      } else if (entry.isFile() && (await isGeneratedFile(full))) {
        await fs.rm(full);
        result.removed.push(full);
      } else {
        result.kept.push(full);
        empty = false;
      }
    }
    return empty;
  };

  if (await visit(outputDir)) await fs.rm(outputDir, { recursive: true, force: true });
  return result;
}

/** Writes `files`, creating directories as needed. */
export async function writeGeneratedFiles(
  files: readonly { path: string; content: string }[],
): Promise<void> {
  for (const file of files) {
    await fs.mkdir(path.dirname(file.path), { recursive: true });
    await fs.writeFile(file.path, file.content, 'utf8');
  }
}
